-- Lot 202 : payloads 31 a 60 sur 1299.
--
-- Chaque commande recoit un texte propre a ChatGPT, a Claude et a Gemini.
-- Rien n'est supprime : l'ancienne version quitte le courant et reste lisible
-- dans l'historique, ce qui suffit a revenir en arriere.

drop table if exists lot_v5_payloads;
create temporary table lot_v5_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-044","moteur":"chatgpt","payload":"[RaccourcIA — /infographic]\n\nMISSION\nTransformer une idee en infographie visuelle. Hiérarchise un titre, trois à cinq messages et les sources utiles. Respecte unités et proportions des données, évite les chiffres décoratifs et le texte minuscule.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel contenu exact dois-je intégrer pour « points cles » ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Infographie claire » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Hiérarchise un titre, trois à cinq messages et les sources utiles. Respecte unités et proportions des données, évite les chiffres décoratifs et le texte minuscule. Le format par défaut est 16:9 en haute définition; adapte-le au canal explicite. Si du texte est nécessaire, utilise le texte exact fourni ou demande uniquement l’information manquante. Si le texte peut être créé, propose une version courte et exacte; sinon choisis le mode sans texte.\n\nPRÉSERVER\nConserve l’enveloppe, les proportions, l’orientation et les repères vérifiés du sujet; distingue clairement représentation réelle et conceptuelle.\n\nÉVITER\nÉvite composants inventés présentés comme réels, cotes déduites sans échelle, légendes illisibles, perspective impossible et fausse précision. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"e8c31122c679d77b46b2889f99ebc3ead0fb474313efb7e8d26047351b4f7686"},{"ref":"RCI-IMG-044","moteur":"claude","payload":"[RaccourcIA — /infographic]\n\nMISSION\nTransformer une idee en infographie visuelle. Hiérarchise un titre, trois à cinq messages et les sources utiles. Respecte unités et proportions des données, évite les chiffres décoratifs et le texte minuscule.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel contenu exact dois-je intégrer pour « points cles » ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Infographie claire » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Hiérarchise un titre, trois à cinq messages et les sources utiles. Respecte unités et proportions des données, évite les chiffres décoratifs et le texte minuscule. Le format par défaut est 16:9 en haute définition; adapte-le au canal explicite. Si du texte est nécessaire, utilise le texte exact fourni ou demande uniquement l’information manquante. Si le texte peut être créé, propose une version courte et exacte; sinon choisis le mode sans texte.\n\nPRÉSERVER\nConserve l’enveloppe, les proportions, l’orientation et les repères vérifiés du sujet; distingue clairement représentation réelle et conceptuelle.\n\nÉVITER\nÉvite composants inventés présentés comme réels, cotes déduites sans échelle, légendes illisibles, perspective impossible et fausse précision. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Sans moteur image connecté, livre un brief de transfert autonome, précis et exploitable. Ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"cd630b3fce0efc394a0338d77c0509c53999c5d75dcd8e836cb5ecdbd01a71e4"},{"ref":"RCI-IMG-044","moteur":"gemini","payload":"[RaccourcIA — /infographic]\n\nMISSION\nTransformer une idee en infographie visuelle. Hiérarchise un titre, trois à cinq messages et les sources utiles. Respecte unités et proportions des données, évite les chiffres décoratifs et le texte minuscule.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte. Relie clairement chaque référence à son rôle : sujet, style, marque, données ou composition. Exécute immédiatement si le sujet et le résul